{"explanation":"Agregar gestion de claves Nostr en memoria con soporte nsec/hex y pruebas unitarias","input":"*** Begin Patch
*** Add File: /Users/nbadilla/Documents/Gobierno/nostr-app/internal/keymgr/manager.go
+package keymgr
+
+import (
+	"encoding/hex"
+	"errors"
+	"strings"
+	"sync"
+
+	"fiatjaf.com/nostr"
+	"fiatjaf.com/nostr/nip19"
+)
+
+var (
+	ErrInvalidSecret = errors.New("invalid secret key format")
+	ErrNoSecret      = errors.New("no secret key loaded")
+)
+
+// Identity exposes only public data derived from the in-memory secret key.
+type Identity struct {
+	PubKeyHex string
+	NPub      string
+}
+
+// Manager keeps a single Nostr secret key in memory.
+type Manager struct {
+	mu     sync.RWMutex
+	secret nostr.SecretKey
+	loaded bool
+}
+
+// New returns an empty in-memory key manager.
+func New() *Manager {
+	return &Manager{}
+}
+
+// Import validates and loads a secret key in nsec or 64-char hex format.
+func (m *Manager) Import(input string) (Identity, error) {
+	sk, err := ParseSecret(input)
+	if err != nil {
+		return Identity{}, err
+	}
+
+	m.setSecret(sk)
+	return deriveIdentity(sk), nil
+}
+
+// Generate creates a new Nostr secret key and keeps it in memory.
+func (m *Manager) Generate() (Identity, error) {
+	sk := nostr.Generate()
+	m.setSecret(sk)
+	return deriveIdentity(sk), nil
+}
+
+// CurrentIdentity derives pubkey and npub from the loaded in-memory secret.
+func (m *Manager) CurrentIdentity() (Identity, error) {
+	m.mu.RLock()
+	sk := m.secret
+	loaded := m.loaded
+	m.mu.RUnlock()
+
+	if !loaded {
+		return Identity{}, ErrNoSecret
+	}
+
+	return deriveIdentity(sk), nil
+}
+
+// HasSecret reports whether a secret is currently loaded in memory.
+func (m *Manager) HasSecret() bool {
+	m.mu.RLock()
+	defer m.mu.RUnlock()
+	return m.loaded
+}
+
+// Clear removes the secret key from memory.
+func (m *Manager) Clear() {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	for i := range m.secret {
+		m.secret[i] = 0
+	}
+	m.loaded = false
+}
+
+// ParseSecret validates and parses either nsec or 64-char hex into a secret key.
+func ParseSecret(input string) (nostr.SecretKey, error) {
+	clean := strings.TrimSpace(input)
+	if clean == "" {
+		return nostr.SecretKey{}, ErrInvalidSecret
+	}
+
+	lower := strings.ToLower(clean)
+	if strings.HasPrefix(lower, "nsec1") {
+		prefix, value, err := nip19.Decode(lower)
+		if err != nil || prefix != "nsec" {
+			return nostr.SecretKey{}, ErrInvalidSecret
+		}
+
+		sk, ok := value.(nostr.SecretKey)
+		if !ok {
+			return nostr.SecretKey{}, ErrInvalidSecret
+		}
+
+		return sk, nil
+	}
+
+	if len(clean) != 64 {
+		return nostr.SecretKey{}, ErrInvalidSecret
+	}
+
+	if _, err := hex.DecodeString(clean); err != nil {
+		return nostr.SecretKey{}, ErrInvalidSecret
+	}
+
+	sk, err := nostr.SecretKeyFromHex(lower)
+	if err != nil {
+		return nostr.SecretKey{}, ErrInvalidSecret
+	}
+
+	return sk, nil
+}
+
+func deriveIdentity(sk nostr.SecretKey) Identity {
+	pk := sk.Public()
+
+	return Identity{
+		PubKeyHex: pk.Hex(),
+		NPub:      nip19.EncodeNpub(pk),
+	}
+}
+
+func (m *Manager) setSecret(next nostr.SecretKey) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	for i := range m.secret {
+		m.secret[i] = 0
+	}
+
+	m.secret = next
+	m.loaded = true
+}
+
*** Add File: /Users/nbadilla/Documents/Gobierno/nostr-app/internal/keymgr/manager_test.go
+package keymgr
+
+import (
+	"strings"
+	"testing"
+
+	"fiatjaf.com/nostr"
+	"fiatjaf.com/nostr/nip19"
+)
+
+func TestParseSecretHex(t *testing.T) {
+	hexSecret := strings.Repeat("1", 64)
+
+	sk, err := ParseSecret(hexSecret)
+	if err != nil {
+		t.Fatalf("ParseSecret() error = %v", err)
+	}
+
+	if got := sk.Hex(); got != hexSecret {
+		t.Fatalf("expected hex %q, got %q", hexSecret, got)
+	}
+}
+
+func TestParseSecretNsec(t *testing.T) {
+	hexSecret := strings.Repeat("2", 64)
+	sk, err := nostr.SecretKeyFromHex(hexSecret)
+	if err != nil {
+		t.Fatalf("SecretKeyFromHex() setup error = %v", err)
+	}
+
+	nsec := nip19.EncodeNsec(sk)
+	got, err := ParseSecret(nsec)
+	if err != nil {
+		t.Fatalf("ParseSecret() error = %v", err)
+	}
+
+	if got.Hex() != hexSecret {
+		t.Fatalf("expected key %q, got %q", hexSecret, got.Hex())
+	}
+}
+
+func TestParseSecretInvalid(t *testing.T) {
+	tests := []string{
+		"",
+		"  ",
+		"deadbeef",
+		strings.Repeat("z", 64),
+		"npub1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq",
+	}
+
+	for _, tc := range tests {
+		t.Run(tc, func(t *testing.T) {
+			_, err := ParseSecret(tc)
+			if err == nil {
+				t.Fatal("expected error, got nil")
+			}
+			if err != ErrInvalidSecret {
+				t.Fatalf("expected ErrInvalidSecret, got %v", err)
+			}
+		})
+	}
+}
+
+func TestManagerImportAndCurrentIdentity(t *testing.T) {
+	hexSecret := strings.Repeat("3", 64)
+	sk, err := nostr.SecretKeyFromHex(hexSecret)
+	if err != nil {
+		t.Fatalf("SecretKeyFromHex() setup error = %v", err)
+	}
+
+	expectedPK := sk.Public()
+	expectedNPub := nip19.EncodeNpub(expectedPK)
+
+	m := New()
+	id, err := m.Import(hexSecret)
+	if err != nil {
+		t.Fatalf("Import() error = %v", err)
+	}
+
+	if !m.HasSecret() {
+		t.Fatal("expected manager to have secret after import")
+	}
+
+	if id.PubKeyHex != expectedPK.Hex() {
+		t.Fatalf("expected pubkey %q, got %q", expectedPK.Hex(), id.PubKeyHex)
+	}
+
+	if id.NPub != expectedNPub {
+		t.Fatalf("expected npub %q, got %q", expectedNPub, id.NPub)
+	}
+
+	current, err := m.CurrentIdentity()
+	if err != nil {
+		t.Fatalf("CurrentIdentity() error = %v", err)
+	}
+
+	if current != id {
+		t.Fatalf("expected current identity %+v, got %+v", id, current)
+	}
+}
+
+func TestManagerGenerateAndClear(t *testing.T) {
+	m := New()
+
+	id, err := m.Generate()
+	if err != nil {
+		t.Fatalf("Generate() error = %v", err)
+	}
+
+	if id.PubKeyHex == "" || id.NPub == "" {
+		t.Fatalf("expected non-empty identity, got %+v", id)
+	}
+
+	if !strings.HasPrefix(id.NPub, "npub1") {
+		t.Fatalf("expected npub prefix, got %q", id.NPub)
+	}
+
+	if !m.HasSecret() {
+		t.Fatal("expected manager to have secret after generate")
+	}
+
+	m.Clear()
+
+	if m.HasSecret() {
+		t.Fatal("expected manager to be empty after clear")
+	}
+
+	_, err = m.CurrentIdentity()
+	if err != ErrNoSecret {
+		t.Fatalf("expected ErrNoSecret after clear, got %v", err)
+	}
+}
+
*** End Patch"}

