+	return &Service{
+		userSecret:      userSecret,
+		userPublicKey:   userSecret.Public(),
+		transportSecret: transportSecret,
+		transportPubKey: transportSecret.Public(),
+		relays:          normalizedRelays,
+		bunkerSecret:    bunkerSecret,
+	}, nil
+}
+
