+	conversationKey, err := nip44.GenerateConversationKey(event.PubKey, s.transportSecret)
+	if err != nil {
+		return req, resp, responseEvent, fmt.Errorf("generate conversation key: %w", err)
+	}
+
+	plain, err := nip44.Decrypt(event.Content, conversationKey)
+	if err != nil {
+		return req, resp, responseEvent, fmt.Errorf("decrypt request: %w", err)
+	}
