+	svc := mustNewService(t)
+	client1 := mustSecretFromHex(t, strings.Repeat("6", 64))
+	client2 := mustSecretFromHex(t, strings.Repeat("7", 64))
+
+	_ = call(t, svc, client1, Request{
+		ID:     "c-1",
+		Method: "connect",
+		Params: []string{client1.Public().Hex(), "bunker-secret"},
+	})
